/*
 * A183119  Magnetic Tower of Hanoi, total number of moves generated by a
 *          certain algorithm, yielding a "forward moving" non-optimal
 *          solution of the [RED ; NEUTRAL ; BLUE] pre-colored puzzle.
 * https://oeis.org/A183119
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(0)=0, a(1)=1, a(n)=a(n-2)+3^(n-1)+1 for n≥2
 * Range:     u8 n <= 5, u16 n <= 10, u32 n <= 21, u64 n <= 41, u128 n <= 81,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0) return 0;
    if (n == 1) return 1;

    seq_t prev2 = 0;   /* a(0)   */
    seq_t prev1 = 1;   /* a(1)   */
    seq_t pow3  = 1;   /* 3^0    */

    for (idx_t i = 2; i <= n; ++i) {
        pow3 = pow3 * 3;                 /* now 3^(i-1)   */
        seq_t curr = prev2 + pow3 + 1;   /* a(i)         */
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}
